function start(folioId: string, clientAvailable = true, brief: ProjectBrief | null = null) {
  const schema = new Schema({
    nodes: {
      doc: { content: "paragraph+" },
      paragraph: { content: "text*", group: "block" },
      text: { group: "inline" },
    },
    marks: { italic: {} },
  });
  const doc = schema.node("doc", null, [
    schema.node("paragraph", null, [
      schema.text("Reading "),
      schema.text("The Odyssey", [schema.mark("italic")]),
      schema.text(
        " sends me back to the long salt roads where traders weighed their loads and followed the coast before dawn.",
      ),
    ]),
  ]);
  const listeners = new Map<string, Set<(event: { transaction: Transaction }) => void>>();
  let state = EditorState.create({ doc, selection: TextSelection.create(doc, 1) });
  let destroyed = false;
  const editor = {
    get isDestroyed() { return destroyed; },
    get state() { return state; },
    view: { hasFocus: () => true },
    on: (name: string, listener: (event: { transaction: Transaction }) => void) => {
      if (!listeners.has(name)) listeners.set(name, new Set());
      listeners.get(name)!.add(listener);
    },
    off: (name: string, listener: (event: { transaction: Transaction }) => void) => {
      listeners.get(name)?.delete(listener);
    },
  } as unknown as Editor;
  const stop = startFlowConductor(editor, {
    folioId,
    brief,
    getClient: () => clientAvailable ? ({}) as ConvexClient : null,
  });
  cleanups.push(stop);
  const tick = ticks.get(nextInterval)!;
  const edit = (text: string, deleted = 0) => {
    const transaction = state.tr;
    const end = transaction.doc.content.size - 1;
    if (deleted) transaction.delete(Math.max(1, end - deleted), end);
    if (text) transaction.insertText(text, transaction.doc.content.size - 1);
    transaction.setSelection(TextSelection.create(transaction.doc, transaction.doc.content.size - 1));
    state = state.apply(transaction);
    for (const listener of listeners.get("transaction") ?? []) listener({ transaction });
  };
  const destroy = () => {
    destroyed = true;
    for (const listener of listeners.get("destroy") ?? []) listener({ transaction: state.tr });
  };
  return { stop, tick, editor, edit, destroy };
}

function clock() {
  let now = 10_000_000;
  const spy = spyOn(Date, "now").mockImplementation(() => now);
  restoreClock = () => spy.mockRestore();
  return { advance: (ms: number) => { now += ms; } };
}

async function enterFlow(current: ReturnType<typeof start>, time: ReturnType<typeof clock>) {
  await flush();
  for (let i = 0; i <= 90; i++) {
    current.edit(" word");
    if (i < 90) time.advance(1_000);
  }
  current.tick();
  await flush();
  expect(flowSnapshot().mode).toBe("flow");
}

function collectSessions() {
  const sessions: FlowSession[] = [];
  const onSession = (event: Event) => sessions.push((event as CustomEvent<FlowSession>).detail);
  window.addEventListener(FLOW_SESSION_EVENT, onSession);
  cleanups.push(() => window.removeEventListener(FLOW_SESSION_EVENT, onSession));
  return sessions;
}

function circle(current: ReturnType<typeof start>, time: ReturnType<typeof clock>, strong = true) {
  current.edit(strong ? "" : " word".repeat(7), strong ? 40 : 25);
  time.advance(18_000);
  current.tick();
  expect(flowSnapshot().mode).toBe("stuck");
}

