import { closeHistory, isHistoryTransaction } from "@tiptap/pm/history";
import type { ConvexClient } from "convex/browser";
import {
  EMPTY_LIVING_DESK, LIVING_DESK_OPEN_KEY, LIVING_DESK_TOGGLE_EVENT,
  publishLivingDesk, registerLivingDeskController,
  type LivingDeskSnapshot, type LivingDeskController, type Occurrence, type Finding,
} from "../../../utils/living-desk-contract";
import { segmentDocument, posAtOffset, type Segments } from "../../../utils/living-desk/segment";
import { analyzeDesk } from "../../../utils/living-desk/analyze";
