import { buildScore, rankFindings, ruleValues, type Confirmation } from "../../../utils/living-desk/score";
import { liveReviewSnapshot, LIVE_REVIEW_REQUEST_EVENT } from "../../../utils/live-review";
import { askJudgement } from "../../../utils/judgement-client";
import { systemOneWait, spendSystemOne, backOffSystemOne } from "../../../utils/system-one-budget";

const key = new PluginKey<DecorationSet>("livingDeskDecorations");
export const LivingDeskDecorations = Extension.create({
  name: "livingDeskDecorations",
  addProseMirrorPlugins() {
    return [new Plugin<DecorationSet>({ key, state: { init: () => DecorationSet.empty, apply: (tr, previous) => tr.getMeta(key) ?? previous.map(tr.mapping, tr.doc) }, props: { decorations: (state) => key.getState(state) } })];
  },
});

/** Last complete pass, for profiling without adding work to a transaction listener. */
export let livingDeskRecomputeMs = 0;

export function startLivingDesk(editor: Editor, options: { getClient: () => ConvexClient | null | undefined; folioId: string }): () => void {
  let stopped = false, running = false, lastEdit = Date.now(), revision = 0;
  let ruleTimer: ReturnType<typeof setTimeout> | undefined;
  let judgementTimer: ReturnType<typeof setTimeout> | undefined;
  let flashTimer: ReturnType<typeof setTimeout> | undefined;
  let idle: number | undefined;
  let confirmation: Confirmation | null = null;
  let confirmedToken = "";
  let segments: Segments = { blocks: [], sections: [], plainText: "" };
  let analysis: ReturnType<typeof analyzeDesk> | null = null;
  const cache: StanceCache = new Map();
  const retained = new Map<string, Finding>();
  const peaks = new Map<string, number>();
  const deliberate = new Set<string>();
  const deliberateCounts = new Map<string, number>();
  const deliberateKey = `living-desk-deliberate:${options.folioId}`;
  const countKey = `${deliberateKey}:counts`;
  let flashes: { from: number; to: number }[] = [];
  let snapshot: LivingDeskSnapshot = { ...EMPTY_LIVING_DESK, folioId: options.folioId, judgement: "idle" };
  try {
    snapshot.open = window.localStorage.getItem(LIVING_DESK_OPEN_KEY) === "true";
    const ids: unknown = JSON.parse(window.localStorage.getItem(deliberateKey) ?? "[]");
    if (Array.isArray(ids)) ids.filter((id): id is string => typeof id === "string").forEach((id) => deliberate.add(id));
    const counts: unknown = JSON.parse(window.localStorage.getItem(countKey) ?? "{}");
    if (counts && typeof counts === "object") Object.entries(counts).forEach(([id, value]) => { if (typeof value === "number") deliberateCounts.set(id, value); });
  } catch { /* Storage can be disabled; the desk still works for this session. */ }

  const draw = () => {
    if (stopped || editor.isDestroyed) return;
    const dom = editor.view.dom;
