const block = (text: string, paragraph = 1, section = 0): Block => ({ text, paragraph, section, pos: paragraph * 1000, kind: "paragraph" });
const prefix = "I walked. My map helped me. I remembered my home. I knew myself. I kept my notes. ";

test("segmentation retains heading sections, block exclusions and inline atom positions", () => {
  const schema = new Schema({ nodes: { doc: { content: "block+" }, text: { group: "inline" }, paragraph: { group: "block", content: "inline*" }, heading: { group: "block", content: "inline*" }, blockquote: { group: "block", content: "block+" }, codeBlock: { group: "block", content: "text*" }, atom: { group: "inline", inline: true, atom: true } } });
  const p = schema.nodes.paragraph.create(null, [schema.text("Hello"), schema.nodes.atom.create(), schema.text(" world")]);
  const doc = schema.nodes.doc.create(null, [p, schema.nodes.heading.create(null, schema.text("Arrival")), schema.nodes.blockquote.create(null, schema.nodes.paragraph.create(null, schema.text("We believe."))), schema.nodes.codeBlock.create(null, schema.text("we"))]);
  const data = segmentDocument(doc);
  expect(data.blocks.map((b) => b.kind)).toEqual(["paragraph", "heading", "quote", "code"]);
  expect(data.sections.map((s) => s.title)).toEqual(["Opening", "Arrival"]);
  expect(data.blocks[0].text).toBe("Hello world");
  expect(posAtOffset(data.blocks[0], 5)).toBe(7);
  expect(posAtOffset(data.blocks[0], 5, true)).toBe(6);
  expect(posAtOffset(data.blocks[0], 11, true)).toBe(13);
  expect(data.blocks[2].paragraph).toBe(2);
  const startsWithHeading = segmentDocument(schema.nodes.doc.create(null, schema.nodes.heading.create(null, schema.text("First"))));
  expect(startsWithHeading.sections).toHaveLength(1);
});

describe("stance", () => {
  test("rule labels separate author, reader, group and unknown; quotes and code are excluded", () => {
    const result = analyzeStance([block(prefix + "We argue for a bridge. As we'll see, it helps. We both visited. We wandered. “We think it is fine,” she said. \"Our thesis is fine.\""), { ...block("we argue I I I"), kind: "quote" }, { ...block("we believe I I I"), kind: "code" }]);
    expect(result.plural).toBe(4);
    expect(result.finding?.count).toBe(1);
    expect(result.candidates.map((c) => c.occurrence.label)).toEqual(["editorial", "inclusive", "group", "unclassified"]);
    expect(result.candidates[0].occurrence.fix).toBe("I");
  });
  test("threshold excludes mainly plural essays and fewer than three singular tokens", () => {
    expect(analyzeStance([block("I agree. We argue. We believe. We think.")]).finding).toBeNull();
    expect(analyzeStance([block("I agree with my friend. We think.")]).finding).toBeNull();
    expect(analyzeStance([block("I know my mind and myself. We think.")]).finding?.count).toBe(1);
  });
  test("inclusive, group and editorial phrases cover the prescribed rule forms", () => {
    for (const phrase of ["As we have seen", "Let us consider", "Let's consider", "We can see"]) expect(analyzeStance([block(prefix + phrase + ".")]).candidates[0].occurrence.label).toBe("inclusive");
    for (const phrase of ["We kids", "We children", "We students", "We villagers", "We all", "My family and I arrived. We ate"]) expect(analyzeStance([block(prefix + phrase + ".")]).candidates.at(-1)?.occurrence.label).toBe("group");
    for (const phrase of ["We would argue", "We contend", "We believe", "We must admit", "We think", "In our view", "Our argument", "Our thesis", "We have shown", "We will show"]) expect(analyzeStance([block(prefix + phrase + ".")]).candidates[0].occurrence.flagged).toBe(true);
  });
  test("agreement and case preserve exact replacement spans", () => {
    const pairs = [["we are ready", "I am", "we are"], ["we were ready", "I was", "we were"], ["We're ready", "I'm", "We're"], ["we’re ready", "I’m", "we’re"], ["WE ARE ready", "I AM", "WE ARE"], ["we've arrived", "I", "we"], ["we'd go", "I", "we"], ["we'll go", "I", "we"], ["us", "me", "us"], ["Our", "My", "Our"], ["ours", "mine", "ours"], ["ourselves", "myself", "ourselves"]];
    for (const [text, fix, span] of pairs) expect(agreementFix(text, 0)).toEqual({ fix, length: span.length });
  });
  test("Jev overrides rules and maps author-alone probability, batches at 24, caches sentences", async () => {
    const cache: StanceCache = new Map();
    const analysis = analyzeStance([block(prefix + "We argue here. We wander there.")]);
    let calls = 0;
    const ask = async (request: Parameters<Parameters<typeof classifyStance>[2]>[0]) => {
      calls++;
      expect(request.questions.stance0.criteria).toEqual(STANCE_OPTIONS);
      expect(request.state.counts).toContain("singular");
      return { ok: true, answers: Object.fromEntries(Object.keys(request.questions).map((key, i) => [key, { type: "choice", choice: STANCE_OPTIONS[i === 0 ? 1 : 0], probabilities: Object.fromEntries(STANCE_OPTIONS.map((o, j) => [o, j === (i === 0 ? 1 : 0) ? 0.8 : 0.05])), confidence: 0.8 }])) };
    };
    await classifyStance(analysis, cache, ask);
    const read = analyzeStance([block(prefix + "We argue here. We wander there.")], cache);
    expect(read.candidates[0].occurrence.flagged).toBe(false);
    expect(read.candidates[1].occurrence).toMatchObject({ flagged: true, provenance: "jev", probability: 0.8, note: "the author alone" });
    await classifyStance(read, cache, ask);
    expect(calls).toBe(1);
