import { expect, test } from "bun:test";
import { withEditor } from "../test-harness";
import { LivingDeskDecorations, startLivingDesk, livingDeskRecomputeMs } from "./living-desk";
import { livingDeskController, livingDeskSnapshot, LIVING_DESK_TOGGLE_EVENT } from "../../../utils/living-desk-contract";
import { LIVE_REVIEW_REQUEST_EVENT } from "../../../utils/live-review";

const content = "<p>I remember my home. I kept my map. I trusted myself and my notes. We argue for the bridge. We think it helps.</p>";
test("fix updates manuscript, count and score in one frame; undo restores everything", async () => {
  await withEditor({ content, extensions: [LivingDeskDecorations] }, ({ editor }) => {
    const stop = startLivingDesk(editor, { folioId: "test", getClient: () => null });
    try {
      const controller = livingDeskController()!;
      const initial = livingDeskSnapshot();
      const stance = initial.findings.find((f) => f.id === "stance")!;
      expect(stance.count).toBe(2);
      controller.focus("stance");
      controller.preview(stance.occurrences[0].id);
      expect(editor.view.dom.querySelector(".ld-ghost")?.textContent).toBe("I");
      expect(editor.view.dom.getAttribute("data-ld-focus")).toBe("stance");
      editor.view.dom.dispatchEvent(new window.KeyboardEvent("keydown", { key: "ArrowRight" }));
      expect(editor.view.dom.hasAttribute("data-ld-focus")).toBe(false);
      const start = performance.now();
      expect(controller.applyFix("stance", stance.occurrences[0].id)).toBe(true);
      expect(performance.now() - start).toBeLessThan(300);
      expect(editor.getText()).toContain("I argue for the bridge");
      expect(livingDeskSnapshot().findings.find((f) => f.id === "stance")?.count).toBe(1);
      expect(livingDeskSnapshot().score.criteria.find((c) => c.key === "consistency")?.value).toBeCloseTo(9.7);
      expect(livingDeskSnapshot().score.lastChange).toMatchObject({ criterion: "consistency", source: "¶1", delta: expect.closeTo(0.3) });
      expect(editor.view.dom.querySelector(".ld-flash")).not.toBeNull();
      expect(editor.commands.undo()).toBe(true);
      expect(editor.getText()).toContain("We argue for the bridge");
      expect(livingDeskSnapshot().findings.find((f) => f.id === "stance")?.count).toBe(2);
      expect(livingDeskSnapshot().score.criteria.find((c) => c.key === "consistency")?.value).toBeCloseTo(9.4);
    } finally { stop(); }
  });
});

test("applyAll is a single undo event and controller dispatches the review and toggle events", async () => {
  await withEditor({ content, extensions: [LivingDeskDecorations] }, ({ editor }) => {
    const stop = startLivingDesk(editor, { folioId: "batch", getClient: () => undefined });
    try {
      const controller = livingDeskController()!;
      expect(controller.applyAll("stance")).toBe(2);
      expect(livingDeskSnapshot().findings.find((f) => f.id === "stance")?.state).toBe("resolved");
      expect(editor.commands.undo()).toBe(true);
      expect(livingDeskSnapshot().findings.find((f) => f.id === "stance")?.count).toBe(2);
      let requested: unknown;
      const listener = (event: Event) => { requested = (event as CustomEvent).detail; };
      window.addEventListener(LIVE_REVIEW_REQUEST_EVENT, listener);
      controller.confirm();
      window.removeEventListener(LIVE_REVIEW_REQUEST_EVENT, listener);
      expect(requested).toEqual({ folioId: "batch" });
      window.dispatchEvent(new window.CustomEvent(LIVING_DESK_TOGGLE_EVENT, { detail: { open: true } }));
      expect(livingDeskSnapshot().open).toBe(true);
      controller.markDeliberate("stance", true);
      expect(livingDeskSnapshot().findings.find((f) => f.id === "stance")?.state).toBe("deliberate");
      expect(controller.applyAll("stance")).toBe(0);
      controller.markDeliberate("stance", false);
      expect(controller.applyAll("stance")).toBe(2);
    } finally { stop(); }
    expect(livingDeskController()).toBeNull();
    expect(editor.view.dom.querySelector(".ld-occ")).toBeNull();
  });
});

test("an edited stale span is refused and adjacent inline atoms are preserved", async () => {
  await withEditor({ content, extensions: [LivingDeskDecorations] }, ({ editor }) => {
    const stop = startLivingDesk(editor, { folioId: "stale", getClient: () => null });
    try {
      const old = livingDeskSnapshot().findings.find((f) => f.id === "stance")!.occurrences[0];
      editor.view.dispatch(editor.state.tr.insertText("They", old.from, old.to));
      expect(livingDeskController()!.applyFix("stance", old.id)).toBe(false);
      expect(editor.getText()).toContain("They argue");
      expect(livingDeskSnapshot().findings.find((f) => f.id === "stance")?.occurrences.find((o) => o.id === old.id)?.note).toBe("This changed since it was found");
    } finally { stop(); }
  });
});

test("full editor recompute on a 5k-word manuscript is measured", async () => {
  const text = "I recall my childhood and my home near Hollins. We argue for the color of the sky. " + "The river carried stories past the old village. ".repeat(4);
  await withEditor({ content: Array.from({ length: 100 }, () => `<p>${text}</p>`).join(""), extensions: [LivingDeskDecorations] }, ({ editor }) => {
    const stop = startLivingDesk(editor, { folioId: "perf", getClient: () => null });
    try {
      console.info(`Living desk editor 5,500 words: ${livingDeskRecomputeMs.toFixed(1)} ms (segmentation + analysis + score, before decoration publication)`);
      expect(livingDeskRecomputeMs).toBeLessThan(300);
    } finally { stop(); }
  });
});

